import urllib.request, urllib.parse, json, sys

smiles='Nc3nc(OCc1ccccc1)c2nc[nH]c2n3'
print('SMILES:', smiles, flush=True)

# Try chemical search via RCSB search API
q={
  "query": {
    "type": "terminal",
    "service": "chemical",
    "parameters": {
      "value": smiles,
      "type": "descriptor",
      "match_type": "exact"
    }
  },
  "return_type": "entry",
  "request_options": {"results_content_type": ["experimental"], "paginate": {"start": 0, "rows": 25}}
}
search_url='https://search.rcsb.org/rcsbsearch/v2/query?json=' + urllib.parse.quote(json.dumps(q))
print('Search URL length:', len(search_url), flush=True)
try:
    req=urllib.request.Request(search_url, headers={'User-Agent':'Mozilla/5.0'})
    resp=urllib.request.urlopen(req, timeout=30).read().decode('utf-8','replace')
    print('Search response:', resp[:5000], flush=True)
except Exception as e:
    print('SMILES search ERR', repr(e), flush=True)
    # Try POST
    try:
        post_url='https://search.rcsb.org/rcsbsearch/v2/query'
        data=json.dumps(q).encode()
        req=urllib.request.Request(post_url, data=data, headers={'User-Agent':'Mozilla/5.0','Content-Type':'application/json'})
        resp=urllib.request.urlopen(req, timeout=30).read().decode('utf-8','replace')
        print('POST response:', resp[:5000], flush=True)
    except Exception as e2:
        print('POST search ERR', repr(e2), flush=True)

# Also try searching for the ligand directly in PDB chemical component API
# The SMILES looks like a pterin/folate derivative. Try to find chemical components
print('\n=== Try RCSB chemical component search ===', flush=True)
for term in ['benzyl pterin','aminopterin','pemetrexed','trimethoprim','methotrexate','folate','pterin']:
    try:
        url=f'https://search.rcsb.org/rcsbsearch/v2/query?json=' + urllib.parse.quote(json.dumps({
            "query":{"type":"terminal","service":"text","parameters":{"attribute":"struct_keywords.text","value":term}},
            "return_type":"entry",
            "request_options":{"paginate":{"start":0,"rows":5}}
        }))
        req=urllib.request.Request(url, headers={'User-Agent':'Mozilla/5.0'})
        resp=urllib.request.urlopen(req, timeout=20).read().decode('utf-8','replace')
        j=json.loads(resp)
        total=j.get('total_count',0)
        hits=[r.get('identifier') for r in j.get('result_set',[])]
        print(f'{term}: total={total}, hits={hits}', flush=True)
    except Exception as e:
        print(f'{term}: ERR {repr(e)}', flush=True)
PY
